// Generated by OpenFlex Neo MXML Compiler (MANUALLY FIXED)
// Complete MXML -> Web Components with Full Reactivity

// OpenFlex Reactivity Runtime
const { Signal, Computed, createEffect } = (typeof window !== 'undefined' && window.OpenFlexRuntime)
  ? window.OpenFlexRuntime
  : require('./runtime/openflex-runtime.js');

const todos = new Signal([]);
const filter = new Signal("all");
const newTodoText = new Signal("");
let nextId = 1;

const filteredTodos = new Computed(() => {
  if (filter.value === "active") {
    return todos.value.filter(t => !t.completed);
  }
  else if (filter.value === "completed") {
    return todos.value.filter(t => t.completed);
  }
  return todos.value;
});

const totalCount = new Computed(() => {
  return todos.value.length;
});

const activeCount = new Computed(() => {
  return todos.value.filter(t => !t.completed).length;
});

const completedCount = new Computed(() => {
  return todos.value.filter(t => t.completed).length;
});

const hasCompleted = new Computed(() => {
  return completedCount.value > 0;
});

function addTodo() {
  if (newTodoText.value.trim() === "") return;

  todos.value = [...todos.value, {
    id: nextId++,
    text: newTodoText.value.trim(),
    completed: false
  }];

  newTodoText.value = "";
}

function toggleTodo(id) {
  todos.value = todos.value.map(todo =>
    todo.id === id ? {...todo, completed: !todo.completed} : todo
  );
}

function deleteTodo(id) {
  todos.value = todos.value.filter(t => t.id !== id);
}

function clearCompleted() {
  todos.value = todos.value.filter(t => !t.completed);
}

function setFilter(newFilter) {
  filter.value = newFilter;
}

function handleKeyPress(event) {
  if (event.key === "Enter") {
    addTodo();
  }
}

// Application Component
class AppComponent extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
    this.setupReactivity();
  }

  render() {
    const style = `
      <style>
        :host {
          display: block;
          width: 100%;
          height: 100%;
        }

        * {
          box-sizing: border-box;
          margin: 0;
          padding: 0;
        }

        .neo-application {
          width: 100%;
          min-height: 100vh;
          display: flex;
          align-items: center;
          justify-content: center;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          padding: 20px;
        }

        .neo-panel {
          background: white;
          border-radius: 16px;
          box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
          overflow: hidden;
          width: 700px;
          max-width: 100%;
        }

        .neo-panel-header {
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          padding: 20px;
          font-size: 20px;
          font-weight: bold;
          text-align: center;
        }

        .neo-panel-body {
          padding: 30px;
        }

        .neo-vbox {
          display: flex;
          flex-direction: column;
        }

        .neo-hbox {
          display: flex;
          flex-direction: row;
          align-items: center;
        }

        .gap-10 { gap: 10px; }
        .gap-20 { gap: 20px; }

        .input-todo {
          width: 100%;
          padding: 15px;
          font-size: 16px;
          border: 2px solid #3498db;
          border-radius: 8px;
          outline: none;
        }

        .input-todo:focus {
          border-color: #667eea;
          box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
        }

        .filter-btn {
          padding: 8px 16px;
          border-radius: 6px;
          font-size: 14px;
          cursor: pointer;
          transition: all 0.2s;
          border: none;
        }

        .filter-btn-active {
          background: #3498db;
          color: white;
          font-weight: bold;
        }

        .filter-btn-inactive {
          background: #ecf0f1;
          color: #2c3e50;
        }

        .todo-list {
          max-height: 400px;
          overflow-y: auto;
        }

        .todo-item {
          padding: 15px;
          background: #f8f9fa;
          border-radius: 8px;
          margin-bottom: 10px;
          border-left: 4px solid #3498db;
          transition: all 0.3s ease;
        }

        .todo-item:hover {
          background: #e9ecef;
          transform: translateX(4px);
        }

        .todo-item-completed {
          background: #ecf0f1;
          border-left-color: #95a5a6;
        }

        .todo-text {
          flex: 1;
          font-size: 16px;
          color: #2c3e50;
        }

        .todo-text-completed {
          color: #95a5a6;
          text-decoration: line-through;
        }

        .btn-delete {
          background: #e74c3c;
          color: white;
          padding: 6px 12px;
          border-radius: 6px;
          font-size: 14px;
          border: none;
          cursor: pointer;
        }

        .btn-clear {
          background: #e74c3c;
          color: white;
          padding: 8px 16px;
          border-radius: 6px;
          border: none;
          cursor: pointer;
        }

        .h-align-center {
          justify-content: center;
        }

        .h-align-space-between {
          justify-content: space-between;
        }

        .separator {
          height: 2px;
          width: 100%;
          background: #ecf0f1;
        }

        .label {
          font-size: 14px;
          color: #7f8c8d;
        }

        .label-small {
          font-size: 12px;
          color: #95a5a6;
          text-align: center;
        }

        .label-empty {
          font-size: 14px;
          color: #95a5a6;
          font-style: italic;
          text-align: center;
          padding: 20px;
        }

        .checkbox {
          width: 20px;
          height: 20px;
          cursor: pointer;
        }
      </style>
    `;

    this.shadowRoot.innerHTML = style + `
      <div class="neo-application">
        <div class="neo-panel">
          <div class="neo-panel-header">✅ Lista de Tarefas Reativa</div>
          <div class="neo-panel-body">
            <div class="neo-vbox gap-20">
              <input type="text" id="new-todo" class="input-todo" placeholder="Digite uma nova tarefa..." />

              <div class="neo-hbox gap-10 h-align-center">
                <button class="filter-btn" data-filter="all">Todas (<span id="total-count">0</span>)</button>
                <button class="filter-btn" data-filter="active">Ativas (<span id="active-count">0</span>)</button>
                <button class="filter-btn" data-filter="completed">Completas (<span id="completed-count">0</span>)</button>
              </div>

              <div class="neo-vbox gap-10 todo-list">
                <div id="empty-message" class="label-empty">Nenhuma tarefa para exibir</div>
                <div id="todo-items"></div>
              </div>

              <div class="separator"></div>

              <div class="neo-hbox h-align-space-between">
                <div class="label" id="stats"></div>
                <button id="clear-btn" class="btn-clear" style="display: none;">🗑️ Limpar Completas</button>
              </div>

              <div class="label-small">✨ Construído com OpenFlex Neo + MXML</div>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  setupReactivity() {
    const input = this.shadowRoot.getElementById('new-todo');
    const todoItems = this.shadowRoot.getElementById('todo-items');
    const emptyMessage = this.shadowRoot.getElementById('empty-message');
    const totalCountEl = this.shadowRoot.getElementById('total-count');
    const activeCountEl = this.shadowRoot.getElementById('active-count');
    const completedCountEl = this.shadowRoot.getElementById('completed-count');
    const statsEl = this.shadowRoot.getElementById('stats');
    const clearBtn = this.shadowRoot.getElementById('clear-btn');

    // Input binding
    input.addEventListener('input', (e) => {
      newTodoText.value = e.target.value;
    });

    input.addEventListener('keypress', handleKeyPress);

    // Filter buttons
    this.shadowRoot.querySelectorAll('.filter-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        setFilter(btn.dataset.filter);
      });
    });

    // Clear completed button
    clearBtn.addEventListener('click', clearCompleted);

    // Reactive updates
    createEffect(() => {
      input.value = newTodoText.value;
    });

    createEffect(() => {
      const filtered = filteredTodos.value;

      if (filtered.length === 0) {
        emptyMessage.style.display = 'block';
        todoItems.innerHTML = '';
      } else {
        emptyMessage.style.display = 'none';
        todoItems.innerHTML = filtered.map(todo => `
          <div class="neo-hbox gap-10 todo-item ${todo.completed ? 'todo-item-completed' : ''}">
            <input type="checkbox" class="checkbox" ${todo.completed ? 'checked' : ''} data-id="${todo.id}" />
            <div class="todo-text ${todo.completed ? 'todo-text-completed' : ''}">${todo.text}</div>
            <button class="btn-delete" data-id="${todo.id}">❌</button>
          </div>
        `).join('');

        // Add event listeners
        todoItems.querySelectorAll('.checkbox').forEach(cb => {
          cb.addEventListener('change', () => {
            toggleTodo(parseInt(cb.dataset.id));
          });
        });

        todoItems.querySelectorAll('.btn-delete').forEach(btn => {
          btn.addEventListener('click', () => {
            deleteTodo(parseInt(btn.dataset.id));
          });
        });
      }
    });

    createEffect(() => {
      totalCountEl.textContent = totalCount.value;
      activeCountEl.textContent = activeCount.value;
      completedCountEl.textContent = completedCount.value;

      statsEl.textContent = `📊 ${totalCount.value} total | 🔵 ${activeCount.value} ativas | ✅ ${completedCount.value} completas`;

      clearBtn.style.display = hasCompleted.value ? 'inline-block' : 'none';
    });

    createEffect(() => {
      const currentFilter = filter.value;
      this.shadowRoot.querySelectorAll('.filter-btn').forEach(btn => {
        if (btn.dataset.filter === currentFilter) {
          btn.className = 'filter-btn filter-btn-active';
        } else {
          btn.className = 'filter-btn filter-btn-inactive';
        }
      });
    });
  }
}

customElements.define('app-root', AppComponent);
